INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "高澞向高骈呈吕用之罪状", "start_year": 884, "end_year": 884, "time_original": "中和四年春条，具体月日未载", "dynasty": "唐", "description": "高澞向高骈呈吕用之罪状；高骈没有采纳，次日又将文书示吕用之。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未确定单一地点。", "status": "draft", "id": "8470cba1-5919-50a1-a4c5-501c40d6e6b2"}, {"title": "高澞知舒州事", "start_year": null, "end_year": null, "time_original": "前事后月余；确年待考", "dynasty": "唐", "description": "高骈在高澞进言后一个多月，命高澞知舒州事。", "phases": [], "location_name": "舒州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "d7b7e848-06c8-5b2f-affb-1b6ecdb9f1de"}, {"title": "李神福以旗帜疑兵解舒州之围", "start_year": null, "end_year": null, "time_original": "高澞到舒州之后；确年待考", "dynasty": "唐", "description": "陈儒攻舒州，高澞向庐州求援。杨行愍兵力不足，李神福以多面旗帜营造援兵到来的声势，攻城者夜遁。", "phases": [], "location_name": "舒州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "b74cad38-8ccf-55ea-93fb-d4d2215488df"}, {"title": "吴迥、李本再攻舒州，高澞弃城后被杀", "start_year": null, "end_year": null, "time_original": "前事久之；确年待考", "dynasty": "唐", "description": "吴迥、李本再攻舒州；高澞弃城，高骈派人杀高澞。", "phases": [], "location_name": "舒州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "57f98c97-35f0-552d-9384-f26918a2afe9"}, {"title": "杨行愍部擒斩吴迥、李本", "start_year": null, "end_year": null, "time_original": "舒州再攻之后；确年待考", "dynasty": "唐", "description": "杨行愍遣陶雅、张训等攻吴迥、李本，擒斩二人；以陶雅摄舒州刺史。", "phases": [], "location_name": "舒州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "d2e9ea2d-8766-5c90-87e3-777c275af75d"}, {"title": "田頵击退攻庐州的秦宗权部", "start_year": null, "end_year": null, "time_original": "舒州事后续叙；确年待考", "dynasty": "唐", "description": "秦宗权遣其弟领兵攻庐州、据舒城；杨行愍遣田頵击退。原文未记秦宗权之弟姓名。", "phases": [], "location_name": "庐州、舒城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "dc0ff1ac-9c40-5d39-8bda-ecf6dc48246a"}, {"title": "路审中募兵据鄂州", "start_year": 884, "end_year": 884, "time_original": "中和四年春条，具体月日未载", "dynasty": "唐", "description": "前杭州刺史路审中在黄州得知鄂州刺史崔绍去世后，募兵三千人进入并占据鄂州。", "phases": [], "location_name": "鄂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "3f6d0ada-e960-597e-93bc-3a3aa60292f4"}, {"title": "杜洪逐岳州刺史", "start_year": 884, "end_year": 884, "time_original": "中和四年春条，具体月日未载", "dynasty": "唐", "description": "武昌牙将杜洪逐走岳州刺史，自行取代。原文未记被逐刺史姓名。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "aa05753d-0f2f-525a-abcb-21b2c9f7d84f"}, {"title": "李克用与诸军攻太康、西华", "start_year": 884, "end_year": 884, "time_original": "中和四年夏四月癸巳起", "dynasty": "唐", "description": "李克用会合许、汴、徐、兗之军，四月癸巳拔太康；又攻西华，黄思鄴逃走。", "phases": [], "location_name": "太康、西华", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "b399833b-c439-5b6f-a80e-788b1dea9bf1"}, {"title": "黄巢撤出，陈州之围解除", "start_year": 884, "end_year": 884, "time_original": "中和四年夏四月太康、西华战后", "dynasty": "唐", "description": "黄巢听闻诸军攻取太康、西华后退至故阳里，陈州之围解除。围陈州几三百日是截至此时的累计时长，不把围城起始记作884年。", "phases": [], "location_name": "陈州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "946ee35b-305a-5dcf-9d39-7614a130a5bc"}, {"title": "黄巢军趋汴州并掠尉氏", "start_year": 884, "end_year": 884, "time_original": "中和四年五月癸亥起", "dynasty": "唐", "description": "五月癸亥大雨，黄巢军营受水淹，黄巢又得知李克用到来，遂向汴州方向移动，攻掠尉氏。", "phases": [], "location_name": "尉氏、汴州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "c5a33d17-5913-5140-a0d0-56be2774633d"}, {"title": "尚让逼大梁，朱珍与庞师古击退", "start_year": 884, "end_year": 884, "time_original": "中和四年五月条，王满渡之战前", "dynasty": "唐", "description": "尚让领骑五千进逼大梁至繁台，宣武将朱珍、庞师古将其击退。", "phases": [], "location_name": "繁台", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "88753e6b-4596-530a-8a24-f091e62a839e"}, {"title": "李克用在王满渡击败黄巢军", "start_year": 884, "end_year": 884, "time_original": "中和四年五月戊辰", "dynasty": "唐", "description": "朱全忠向李克用告急；五月戊辰，李克用与田从异追黄巢至王满渡，乘其军半渡而击，大败之。", "phases": [], "location_name": "王满渡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "291e5dbf-47f6-5d5a-8e87-16a3301d2ab3"}, {"title": "尚让等分别归降时溥、朱全忠", "start_year": 884, "end_year": 884, "time_original": "中和四年五月王满渡战后", "dynasty": "唐", "description": "王满渡败后，尚让率众降时溥；李谠、霍存、葛从周、张归霸及从弟张归厚等降朱全忠。", "phases": [], "location_name": "汴州附近", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "7d57cf27-ad38-541a-af6a-0191edc2fdd7"}, {"title": "李克用追黄巢至冤句后还汴", "start_year": 884, "end_year": 884, "time_original": "中和四年五月己巳至辛未", "dynasty": "唐", "description": "李克用先在封丘再败黄巢，追至冤句；因兵马疲乏、粮尽，返回汴州。黄巢向东逃走。", "phases": [], "location_name": "封丘、冤句", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "1d03cf44-0dc5-5f3e-9dba-fb717f94d62d"}, {"title": "高仁厚屯德阳，杨师立部据鹿头关", "start_year": 884, "end_year": 884, "time_original": "中和四年五月癸酉", "dynasty": "唐", "description": "高仁厚屯德阳；杨师立遣郑君雄、张士安据鹿头关抵御。", "phases": [], "location_name": "德阳、鹿头关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "fb2550c3-213e-5e54-822e-45af71a7d9f2"}, {"title": "朱全忠部围攻上源驿，李克用脱险", "start_year": 884, "end_year": 884, "time_original": "中和四年五月甲戌夜", "dynasty": "唐", "description": "李克用甲戌到汴州，朱全忠邀其入城住上源驿。宴后，杨彦洪与朱全忠谋围攻驿馆；李克用在薛志勤、史敬思等护卫下突围，史敬思战死。", "phases": [], "location_name": "汴州上源驿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "12e041e7-b8d8-56f5-9cb9-4d78341639b6"}, {"title": "上源驿当夜朱全忠射杀杨彦洪", "start_year": 884, "end_year": 884, "time_original": "中和四年五月甲戌夜", "dynasty": "唐", "description": "上源驿事变当夜，杨彦洪骑马行于朱全忠前，朱全忠射杀杨彦洪。", "phases": [], "location_name": "汴州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "25bb3d94-c0c2-5708-a207-4897a2909b73"}, {"title": "刘氏劝李克用向朝廷申诉", "start_year": 884, "end_year": 884, "time_original": "上源驿事变次晨，五月条", "dynasty": "唐", "description": "李克用妻刘氏劝阻其立即攻打朱全忠，建议向朝廷申诉；李克用听从并率军离去。", "phases": [], "location_name": "汴州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "5a5fbe34-3f7b-53d6-b8f0-d52297613633"}, {"title": "李克用与朱全忠互致书信争论事变", "start_year": 884, "end_year": 884, "time_original": "上源驿事变次日或稍后，具体日期未载", "dynasty": "唐", "description": "李克用书信责朱全忠。朱全忠回信声称自己不知前夜事变，称由朝廷使者与杨彦洪谋划；这是其自辩之辞，不能直接当作事实。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未确定单一地点。", "status": "draft", "id": "2f6e9096-39be-53d9-add4-41015bd20ad1"}, {"title": "李克用求粮不获后返回晋阳", "start_year": 884, "end_year": 884, "time_original": "中和四年五月丙子以后", "dynasty": "唐", "description": "李克用五月丙子到许州故寨，向周岌求粮未得，于是经陕渡河回晋阳。", "phases": [], "location_name": "许州、晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "c1aaafc4-c435-5e86-9e6d-7b224ba2c3ae"}, {"title": "高仁厚在鹿头关夜袭中击退东川军", "start_year": 884, "end_year": 884, "time_original": "中和四年五月丁丑夜", "dynasty": "唐", "description": "郑君雄、张士安夜袭高仁厚营寨，杨茂言等弃寨；高仁厚设伏击退东川军。", "phases": [], "location_name": "鹿头关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "c33b1d82-4d99-526a-a934-4b057eea36fd"}, {"title": "高仁厚处决杨茂言", "start_year": 884, "end_year": 884, "time_original": "中和四年五月丁丑夜后翌晨", "dynasty": "唐", "description": "高仁厚以弃寨逃走、其后欺瞒为由处决行军副使杨茂言；其余逃散士卒获召回。", "phases": [], "location_name": "鹿头关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "39c4add6-a779-51d7-9209-217d26d256d5"}, {"title": "时溥遣李师悦追黄巢", "start_year": 884, "end_year": 884, "time_original": "中和四年五月庚辰", "dynasty": "唐", "description": "时溥遣李师悦领兵万人追击黄巢。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未确定单一地点。", "status": "draft", "id": "d34d4451-5e84-57dd-ad84-db2c1e4b429a"}, {"title": "高仁厚击败郑君雄并进围梓州", "start_year": 884, "end_year": 884, "time_original": "中和四年五月癸未", "dynasty": "唐", "description": "高仁厚在鹿头关佯败诱敌、设伏击败郑君雄等；敌军当夜退回梓州。陈敬瑄增兵三千，进围梓州。", "phases": [], "location_name": "鹿头关、梓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名，坐标未核。", "status": "draft", "id": "f8bf4adc-fbc0-59a1-8f2b-435264fc571d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

