SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "高澞向高骈呈吕用之罪状；高骈没有采纳，次日又将文书示吕用之。", "citation": "卷255·中和四年（884）·zztj-v255-y0884-p008·原文件第95行", "note": "原文：高骈从子左骁卫大将军澞，疏吕用之罪状二十馀幅，密以呈骈，且泣曰：“用之内则假神仙之说，蛊惑尊听；外则盗节制之权，残贼百姓；将佐惧死，莫之敢言。岁月浸深，羽翼将成，苟不除之，恐高氏弈代勋庸，一朝扫地矣！”因呜咽不自胜。骈曰：“汝醉邪！”命扶出。；核对说明：按此段原文整理；所述范围限于本段与引文，不扩充人物完整生平或精确月日。", "status": "draft", "id": "a9cfd978-6098-59a1-9dac-b9872d58af01", "subject_id": "8470cba1-5919-50a1-a4c5-501c40d6e6b2", "source_id": "da7ef52b-1f83-5062-9ee2-9a4ba60c2c41"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "中和四年春条，具体月日未载", "citation": "卷255·中和四年（884）·zztj-v255-y0884-p008·原文件第95行", "note": "原文：高骈从子左骁卫大将军澞，疏吕用之罪状二十馀幅，密以呈骈，且泣曰：“用之内则假神仙之说，蛊惑尊听；外则盗节制之权，残贼百姓；将佐惧死，莫之敢言。岁月浸深，羽翼将成，苟不除之，恐高氏弈代勋庸，一朝扫地矣！”因呜咽不自胜。骈曰：“汝醉邪！”命扶出。；核对说明：由该年条定位；干支日未换算成公历日。", "status": "draft", "id": "9a0b4fc1-dfdc-54d7-8399-dcd7da97b86b", "subject_id": "8470cba1-5919-50a1-a4c5-501c40d6e6b2", "source_id": "da7ef52b-1f83-5062-9ee2-9a4ba60c2c41"}, {"subject_table": "person", "field_path": "biography", "claim_text": "中和四年条所见：高澞为呈文者。", "citation": "卷255·中和四年（884）·zztj-v255-y0884-p008·原文件第95行", "note": "原文：高骈从子左骁卫大将军澞，疏吕用之罪状二十馀幅，密以呈骈，且泣曰：“用之内则假神仙之说，蛊惑尊听；外则盗节制之权，残贼百姓；将佐惧死，莫之敢言。岁月浸深，羽翼将成，苟不除之，恐高氏弈代勋庸，一朝扫地矣！”因呜咽不自胜。骈曰：“汝醉邪！”命扶出。明日，以澞状示用之，用之曰：“四十郎尝以空乏见告，未获遵命，故有此憾。”因出澞手书数幅呈之。骈甚惭，遂禁澞出入；后月馀，以澞知舒州事。群盗陈儒攻舒州，澞求救于庐州。杨行愍力不能救，谋于其将李神福，神福请不用寸刃而逐之。乃多赍旗帜，间道入舒州，顷之，引舒州兵建庐州旗帜而出，指画地形，若布大陈状；贼惧，宵遁。神福，洺州人也。久之，群盗吴迥、李本复攻舒州，澞不能守，弃城走，骈使人就杀之。杨行愍遣其将合肥陶雅、清流张训等将兵击吴迥、李本，擒斩之，以雅摄州刺史。秦宗权遣其弟将兵寇庐州，据舒城，杨行愍遣其将合肥田頵击走之。；核对说明：按此段原文整理；所述范围限于本段与引文，不扩充人物完整生平或精确月日。", "status": "draft", "id": "75c043bc-5aa3-5f00-b07c-569d69d83f27", "subject_id": "908a369e-03fb-5fd8-94bf-39b35afbde5c", "source_id": "da7ef52b-1f83-5062-9ee2-9a4ba60c2c41"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "高澞：呈文者。", "citation": "卷255